package tv.vela.launcher;

import android.content.Context;
import android.graphics.Color;
import android.view.*;
import android.widget.*;
import java.util.*;

/** A bounded, native content sheet. Owners supply existing metadata and own every request. */
final class VelaContentDetails extends FrameLayout {
    final ImageView image;final TextView heading,metadata,description;final LinearLayout actions;private final ScrollView scroll,synopsis;private ProgressBar progressBar;java.util.function.BooleanSupplier ready=()->true;
    VelaContentDetails(Context c,String title,String meta,String summary,float progress){super(c);setBackground(VelaTheme.panel());setPadding(34,28,34,28);image=new ImageView(c);image.setScaleType(ImageView.ScaleType.FIT_CENTER);image.setBackground(VelaTheme.shape(VelaTheme.CARD,18));image.setClipToOutline(true);put(image,0,0,320,480);heading=text(title,34,VelaTheme.WHITE);heading.setTypeface(Ui.displaySemibold);heading.setMaxLines(2);put(heading,358,0,962,92);metadata=text(meta,20,VelaTheme.SECONDARY);metadata.setMaxLines(2);put(metadata,358,104,962,62);description=text(summary.isEmpty()?L10n.text("No description supplied by this source."):summary,22,VelaTheme.SECONDARY);description.setGravity(Gravity.TOP);description.setPadding(12,10,12,14);synopsis=new ScrollView(c);synopsis.setVerticalScrollBarEnabled(true);synopsis.setScrollBarSize(3);synopsis.setOverScrollMode(OVER_SCROLL_NEVER);synopsis.setFocusable(true);synopsis.setDefaultFocusHighlightEnabled(false);synopsis.setContentDescription(L10n.text("Synopsis"));synopsis.addView(description,new ScrollView.LayoutParams(-1,-2));synopsis.setOnFocusChangeListener((v,f)->{synopsis.setBackground(VelaTheme.shape(f?Appearance.accent(c):Color.TRANSPARENT,16));description.setTextColor(f?VelaTheme.INK:VelaTheme.SECONDARY);});put(synopsis,346,172,974,166);
        if(progress>=0){ProgressBar bar=new ProgressBar(c,null,android.R.attr.progressBarStyleHorizontal);progressBar=bar;bar.setMax(1000);bar.setProgress((int)(Math.max(0,Math.min(1,progress))*1000));bar.setProgressTintList(android.content.res.ColorStateList.valueOf(Appearance.accent(c)));bar.setProgressBackgroundTintList(android.content.res.ColorStateList.valueOf(0x28FFFFFF));put(bar,358,350,962,6);}
        scroll=new ScrollView(c);scroll.setVerticalScrollBarEnabled(false);scroll.setOverScrollMode(OVER_SCROLL_NEVER);actions=new LinearLayout(c);actions.setOrientation(LinearLayout.VERTICAL);actions.setPadding(2,4,2,22);scroll.addView(actions);put(scroll,358,378,962,338);if(VelaReading.scale(c)>1.1f){heading.setTextSize(android.util.TypedValue.COMPLEX_UNIT_PX,Math.min(40,34*VelaReading.scale(c)));move(heading,358,0,962,104);move(metadata,358,118,962,66);move(synopsis,346,188,974,150);}}
    void broadcast(){move(image,0,0,416,234);move(heading,450,0,870,104);move(metadata,450,118,870,86);move(synopsis,-12,262,1332,150);move(scroll,0,448,1320,268);if(progressBar!=null)move(progressBar,0,426,1320,6);}
    @Override public View focusSearch(View focused,int direction){View next=FocusFinder.getInstance().findNextFocus(this,focused,direction);return next==null?focused:next;}
    private void move(View v,int x,int y,int w,int h){LayoutParams lp=new LayoutParams(w,h);lp.leftMargin=x;lp.topMargin=y;v.setLayoutParams(lp);}
    private TextView text(String value,int size,int color){TextView v=new TextView(getContext());v.setText(value);v.setTextSize(android.util.TypedValue.COMPLEX_UNIT_PX,size*VelaReading.scale(getContext()));v.setTextColor(color);v.setTypeface(Ui.medium);v.setIncludeFontPadding(false);v.setGravity(Gravity.CENTER_VERTICAL);return v;}
    private void put(View v,int x,int y,int w,int h){LayoutParams p=new LayoutParams(w,h);p.leftMargin=x;p.topMargin=y;addView(v,p);}
    TextView action(String title,String detail,Runnable click){TextView v=text(title,22,VelaTheme.WHITE);v.setPadding(20,15,20,15);v.setMinHeight(72);v.setFocusable(true);v.setFocusableInTouchMode(true);v.setDefaultFocusHighlightEnabled(false);VelaTheme.rowText(v,title,detail,false);v.setBackground(VelaTheme.row(false,Appearance.accent(getContext())));v.setOnFocusChangeListener((w,f)->{VelaTheme.rowText(v,title,detail,f);v.setBackground(VelaTheme.row(f,Appearance.accent(getContext())));});v.setOnClickListener(w->{if(ready.getAsBoolean())click.run();});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=4;actions.addView(v,lp);return v;}
}
